#navCartSummary>i,#appBottomNav.compact+#navCartSummary>i{display:grid!important;width:31px!important;height:48px!important;place-items:center;border-radius:11px!important;color:#082f49!important;background:linear-gradient(145deg,#ecfeff,#67e8f9)!important;font-size:13px!important;box-shadow:0 6px 13px rgba(0,0,0,.15)!important}
#navCartSummary:hover{transform:translateY(-3px) scale(1.02)!important;box-shadow:0 18px 38px rgba(3,37,65,.48),0 0 0 5px rgba(251,191,36,.16)!important}#navCartSummary:active{transform:scale(.97)!important}
@keyframes vaCartAttention{0%,100%{filter:brightness(1);box-shadow:0 14px 32px rgba(86,10,35,.42),0 0 0 4px rgba(251,191,36,.13)}50%{filter:brightness(1.18);box-shadow:0 17px 38px rgba(190,18,60,.48),0 0 0 8px rgba(251,191,36,.25)}}
#navCartSummary:not([hidden]){animation:vaCartAttention 1.35s ease-in-out infinite}
