#navCartSummary:hover{animation-play-state:paused}
@media(prefers-reduced-motion:reduce){#navCartSummary:not([hidden]),#navCartSummary:not([hidden])>span{animation:none!important}}
@media(max-width:380px){#navCartSummary,#appBottomNav.compact+#navCartSummary{width:176px!important;min-width:176px!important;grid-template-columns:45px minmax(0,1fr) 29px!important}#navCartSummary>span,#appBottomNav.compact+#navCartSummary>span{width:44px!important;height:44px!important}#navCartSummary strong,#appBottomNav.compact+#navCartSummary strong{font-size:14px!important}}
