  border:1px solid rgba(255,255,255,.22)!important;border-radius:28px!important;
  background:
    radial-gradient(circle at 88% 12%,rgba(255,116,76,.72),transparent 32%),
    radial-gradient(circle at 12% 105%,rgba(244,63,94,.35),transparent 38%),
    linear-gradient(112deg,#6f1029 0%,#991832 42%,#c82739 72%,#ef5544 100%)!important;
  box-shadow:0 22px 48px rgba(34,18,49,.34),inset 0 1px 0 rgba(255,255,255,.25),inset 0 -1px 0 rgba(255,255,255,.08)!important;
}
.va-top:before{width:34%!important;height:260%!important;background:linear-gradient(90deg,transparent,rgba(255,255,255,.3),transparent)!important;animation:vaBrandShine 4.7s ease-in-out infinite!important}
.va-top:after{right:-42px!important;bottom:-95px!important;width:205px!important;height:205px!important;border:2px solid rgba(255,227,159,.3)!important;box-shadow:0 0 0 28px rgba(255,202,92,.09),0 0 0 58px rgba(255,255,255,.045)!important}
.va-brand-copy{position:relative;z-index:3;padding:11px 16px!important;border-left:1px solid rgba(255,232,190,.3)!important}
.va-brand-kicker{padding:5px 11px!important;border:1px solid rgba(255,220,135,.5)!important;color:#ffe49d!important;background:rgba(4,10,28,.28)!important;box-shadow:inset 0 1px 0 rgba(255,255,255,.14),0 5px 13px rgba(0,0,0,.12)!important}
.va-brand-copy h1{margin-top:7px!important;font-size:35px!important;letter-spacing:-1px!important;text-shadow:0 5px 18px rgba(0,0,0,.38)!important}
.va-brand-copy h1 em{background-image:linear-gradient(90deg,#fff 0%,#fff 42%,#ffd166 63%,#fff 86%)!important;background-size:230% auto!important}
.va-brand-copy p{margin-top:8px!important;color:#fff!important;font-size:14px!important;font-weight:850!important;text-shadow:0 3px 10px rgba(0,0,0,.34)!important}
.va-neuromodas-logo{position:relative;z-index:3;width:102px!important;height:102px!important;flex-basis:102px!important;padding:5px!important;border:2px solid rgba(255,211,105,.8)!important;border-radius:27px!important;background:#050507!important;box-shadow:0 16px 36px rgba(0,0,0,.48),inset 0 1px 0 rgba(255,255,255,.1),0 0 0 5px rgba(255,211,105,.1),0 0 28px rgba(255,45,72,.32)!important}
.va-neuromodas-logo:before{background:#050507!important;box-shadow:inset 0 0 18px rgba(225,20,52,.12)!important}
.va-neuromodas-logo img{filter:drop-shadow(0 0 11px rgba(255,45,72,.7)) saturate(1.28)!important}
.va-neurosoft-brand.va-neurosoft-new{position:relative;z-index:3;padding:2px!important;border:0!important;background:transparent!important;box-shadow:none!important}.va-neurosoft-brand.va-neurosoft-new:before{display:none!important}.va-neurosoft-brand.va-neurosoft-new img{object-fit:contain!important;filter:drop-shadow(0 8px 13px rgba(66,5,22,.36)) saturate(1.12)!important}
@media(max-width:700px){.va-top{min-height:138px!important;padding:14px 16px!important;border-radius:24px!important}.va-neuromodas-logo{width:86px!important;height:86px!important;flex-basis:86px!important;border-radius:23px!important}.va-brand-copy{padding:8px 11px!important}.va-brand-copy h1{font-size:29px!important}.va-brand-copy p{font-size:12px!important}}
