.va-card.clients{background:radial-gradient(circle at 95% 8%,rgba(253,164,175,.28),transparent 34%),linear-gradient(145deg,#be123c,#f43f5e 62%,#fb7185)!important}
.va-card.history{background:radial-gradient(circle at 94% 8%,rgba(196,181,253,.28),transparent 34%),linear-gradient(145deg,#5b21b6,#8b2fc2 60%,#c026d3)!important}
.va-card.cash{background:radial-gradient(circle at 94% 7%,rgba(254,240,138,.28),transparent 34%),linear-gradient(145deg,#ea580c,#f59e0b 65%,#facc15)!important}
.va-card.purchases{background:radial-gradient(circle at 96% 7%,rgba(103,232,249,.28),transparent 34%),linear-gradient(145deg,#075985,#0891b2 61%,#14b8a6)!important}
