.va-card.sale>i{background:linear-gradient(145deg,rgba(255,255,255,.28),rgba(255,255,255,.12))!important}.va-card.cash>i{color:#7c2d12!important;background:linear-gradient(145deg,#fff7d6,#fed37a)!important;text-shadow:none}
