/* Venta móvil compacta y con acentos vivos. */
.va-app{background:radial-gradient(circle at 8% 2%,rgba(17,169,213,.20),transparent 28%),radial-gradient(circle at 96% 20%,rgba(124,58,237,.14),transparent 24%),linear-gradient(145deg,#eafaff 0%,#f8f6ff 52%,#f2fff4 100%)}
