.va-client-control{display:grid!important;grid-template-columns:minmax(0,1fr) 46px;gap:7px;flex-wrap:nowrap}.va-client-control .va-input{min-width:0}.va-client-control .va-client-search{width:46px;min-width:46px;height:48px;padding:0;border-radius:13px;background:linear-gradient(135deg,#ff8a00,#ffb703);box-shadow:0 7px 16px rgba(255,138,0,.26)}
.va-product-search-field{position:relative;margin-top:2px}.va-product-search-field .va-field-label i{background:linear-gradient(135deg,#00a86b,#20cf86)}.va-product-search-wrap{position:relative}.va-product-search-wrap>i{position:absolute;z-index:2;top:50%;left:15px;color:var(--va-violet);font-size:15px;transform:translateY(-50%)}.va-product-search-wrap .va-input{padding-left:42px;border-color:#bcddeb;background:#fff;box-shadow:0 7px 17px rgba(18,51,83,.07)}
.va-input:focus,.va-select:focus{border-color:#8b5cf6;box-shadow:0 0 0 4px rgba(139,92,246,.13)}.va-total{background:linear-gradient(120deg,#673ab7,#8b5cf6 45%,#08a9ce);box-shadow:0 10px 24px rgba(103,58,183,.22)}.va-btn.green{background:linear-gradient(135deg,#09a85f,#20d67d 65%,#b1e51c)}.va-nav button.active{background:linear-gradient(135deg,#673ab7,#168ed0 65%,#11b8c9)}
.va-btn,.va-title button,.va-card{transition:transform .18s ease,filter .18s ease,box-shadow .18s ease}.va-btn:hover,.va-title button:hover,.va-card:hover{filter:saturate(1.12) brightness(1.03);transform:translateY(-2px)}
