id="editPurchaseProductHasPresentations" type="checkbox"> Activar</label></div><div id="editPurchaseProductPresentations" class="va-edit-presentations"></div></div><div class="va-field va-provider-wide"><label>Descripción</label><textarea id="editPurchaseProductDescription" class="va-input"></textarea></div></div><div class="va-provider-actions"><button type="button" class="va-btn gray" onclick="closeModal('editPurchaseProductModal')">Cancelar</button><button id="saveEditedPurchaseProductBtn" type="button" class="va-btn red" onclick="saveEditedPurchaseProduct()"><i class="fa fa-save"></i> Guardar cambios</button></div></div></div>
