<div id="vaToast" class="va-toast"></div>

<script>
const VA_API='../api/index.php';
const VA_USER=<?= json_encode($appUser) ?>;
const state={warehouse:null,point:null,types:[],categories:[],selectedCategory:'',client:null,defaultClient:null,cart:[],products:[],clientResults:[],cash:{sales:[],income:0,outflow:0}};
let lastRenderedCartTotal=0;
const $=id=>document.getElementById(id);
const money=n=>'S/ '+Number(n||0).toFixed(2);
function asList(v){if(Array.isArray(v))return v;if(Array.isArray(v?.data))return v.data;if(Array.isArray(v?.lista))return v.lista;if(v&&typeof v==='object')return Object.values(v).filter(x=>x&&typeof x==='object');return []}
async function api(path,options={}){const isSale=path==='/ventas'&&String(options.method||'GET').toUpperCase()==='POST',saleSnapshot=isSale?{total:cartTotal(),items:state.cart.map(item=>({name:productDesc(item),qty:item.cantidad,price:item.precio})),client:state.client?.Cliente||state.client?.RazonSocial||'VARIOS',email:state.client?.Email||''}:null,res=await fetch(VA_API+path,{headers:{'Content-Type':'application/json','X-Ventas-App':'1',...(options.headers||{})},...options});const text=await res.text();let data={};try{data=text?JSON.parse(text):{}}catch(e){throw new Error(/stack trace|slim\\|fatal error|<html|<pre/i.test(text)?'No se pudo completar la consulta. Intente nuevamente.':(text&&text.length<180?text:'Respuesta inválida del servidor'))}if(!res.ok||data?.error){const message=String(data?.error||data?.message||'');throw new Error(/stack trace|slim\\|fatal error|<html|<pre/i.test(message)?'No se pudo completar la operación.':message||'No se pudo completar la operación')}if(isSale&&data?.insertId)setTimeout(()=>showSaleSuccess(data.insertId,saleSnapshot),180);return data}
const ventasAppBaseApi=api;
api=async function(path,options={}){if(path==='/ventas'&&String(options.method||'GET').toUpperCase()==='POST'&&String(selectedType()?.CodSunat||'')==='07'){const selected=state.creditNoteDocument,reference=String($('creditNoteReference')?.value||'').trim().toUpperCase(),reason=String($('creditNoteReason')?.value||''),reasonText=$('creditNoteReason')?.selectedOptions?.[0]?.textContent?.trim()||'';if(!selected||reference!==String(selected.NroComprobante||'').toUpperCase())throw new Error('Busque y seleccione una factura o boleta de la lista.');if(!reason)throw new Error('Seleccione el motivo de la nota de crédito.');const payload=JSON.parse(options.body||'{}');payload.CodSunatModifica=String(selected.CodSunat||'');payload.NroComprobanteModifica=reference;payload.NotaIdMotivo=reason;payload.NotaDescMotivo=reasonText;options={...options,body:JSON.stringify(payload)}}return ventasAppBaseApi(path,options)};
function toast(msg,error=false){const el=$('vaToast');el.textContent=msg;el.className='va-toast show'+(error?' error':'');clearTimeout(el._timer);el._timer=setTimeout(()=>el.className='va-toast',3500)}
function setNightMode(enabled){const app=$('ventasApp'),button=$('nightModeToggle');app?.classList.toggle('night-mode',Boolean(enabled));if(button){button.classList.toggle('active',Boolean(enabled));button.setAttribute('aria-pressed',enabled?'true':'false');button.setAttribute('aria-label',enabled?'Desactivar modo nocturno':'Activar modo nocturno');button.title=enabled?'Volver al modo claro':'Activar modo nocturno';button.innerHTML=enabled?'<i class="fa fa-sun-o"></i>':'<i class="fa fa-moon-o"></i>'}}
function setAppBannerHidden(hidden){$('ventasApp')?.classList.toggle('banner-hidden',Boolean(hidden));localStorage.setItem('ventasAppBannerHidden',hidden?'1':'0')}
function toggleNightMode(){const enabled=!$('ventasApp')?.classList.contains('night-mode');localStorage.setItem('ventasAppNightMode',enabled?'1':'0');setNightMode(enabled);toast(enabled?'Modo nocturno activado. Descanso visual habilitado.':'Modo claro activado.')}
function ensureClientDocumentLookup(){const input=$('newClientDoc');if(!input||input.closest('.va-document-lookup'))return;const wrap=document.createElement('div'),button=document.createElement('button');wrap.className='va-document-lookup';button.id='clientDocumentLookupBtn';button.type='button';button.className='va-document-lookup-btn';button.innerHTML='<i class="fa fa-search"></i><span>RENIEC / SUNAT</span>';button.onclick=lookupClientDocument;input.parentNode.insertBefore(wrap,input);wrap.append(input,button);input.addEventListener('keydown',event=>{if(event.key==='Enter'){event.preventDefault();lookupClientDocument()}})}
async function lookupClientDocument(){const input=$('newClientDoc'),button=$('clientDocumentLookupBtn'),number=String(input?.value||'').replace(/\D/g,'');if(number.length!==8&&number.length!==11)return toast('Ingrese 8 dígitos para DNI o 11 para RUC.',true);const type=number.length===8?'DNI':'RUC';input.value=number;if(button){button.disabled=true;button.innerHTML='<i class="fa fa-spinner fa-spin"></i><span>Consultando</span>'}try{const data=await api(`/consultarRUC?type=${encodeURIComponent(type)}&numero=${encodeURIComponent(number)}`),name=type==='DNI'?[data?.nombres,data?.apellidoPaterno,data?.apellidoMaterno].filter(Boolean).join(' '):(data?.razonSocial||''),address=data?.direccion||'';if(!name&&!address)throw new Error(`No se encontró el ${type}.`);if(name)$('newClientName').value=String(name).replace(/\s+/g,' ').trim();$('newClientAddress').value=String(address).replace(/\s+/g,' ').trim();toast(`${type} encontrado. Datos completados correctamente.`)}catch(error){toast(error.message||`No se pudo consultar ${type}.`,true)}finally{if(button){button.disabled=false;button.innerHTML='<i class="fa fa-search"></i><span>RENIEC / SUNAT</span>'}}}
function setSaleCompact(compact){const app=$('ventasApp'),toggle=$('saleCompactToggle');app.classList.toggle('sale-compact',Boolean(compact));if(toggle){toggle.setAttribute('aria-expanded',compact?'false':'true');toggle.setAttribute('aria-label',compact?'Mostrar encabezado y datos':'Ocultar encabezado y datos');toggle.title=compact?'Mostrar encabezado y datos':'Ocultar encabezado y datos';const label=toggle.querySelector('span');if(label)label.textContent=compact?'Mostrar':'Más espacio'}}
function toggleSaleCompact(){const compact=!$('ventasApp').classList.contains('sale-compact');sessionStorage.setItem('ventasAppCompact',compact?'1':'0');setSaleCompact(compact);window.scrollTo({top:0,behavior:'smooth'})}
function setSaleMode(mode){const cartMode=mode==='cart',panel=document.querySelector('.va-sale-panel');panel?.classList.toggle('cart-focus',cartMode);$('showProductsMode')?.classList.toggle('active',!cartMode);$('showCartMode')?.classList.toggle('active',cartMode);if(cartMode){document.querySelector('.va-cart-heading')?.scrollIntoView({behavior:'smooth',block:'start'})}else{document.querySelector('.va-sale-mode-switch')?.scrollIntoView({behavior:'smooth',block:'start'});setTimeout(()=>$('productSearch')?.focus({preventScroll:true}),250)}}
function setNavCompact(compact){const nav=$('appBottomNav'),button=nav?.querySelector('.va-nav-collapse');if(!nav)return;nav.classList.toggle('compact',Boolean(compact));if(button){button.setAttribute('aria-expanded',compact?'false':'true');button.setAttribute('aria-label',compact?'Mostrar menú completo':'Contraer menú');button.title=compact?'Mostrar menú completo':'Contraer menú'}if(document.readyState!=='loading')renderCart()}
function toggleNavCompact(event){event?.stopPropagation();const compact=!$('appBottomNav').classList.contains('compact');localStorage.setItem('neuroAppNavCompact',compact?'1':'0');setNavCompact(compact)}
function showView(name){$('ventasApp')?.classList.toggle('purchases-active',name==='purchases'||name==='stock'||name==='dashboard'||name==='movementRegister'||name==='inventory');$('ventasApp')?.classList.toggle('sale-active',name==='sale');document.querySelectorAll('.va-view').forEach(v=>v.classList.toggle('active',v.dataset.view===name));document.querySelectorAll('.va-nav button').forEach(v=>v.classList.toggle('active',v.dataset.nav===name));setSaleCompact(name==='sale'&&sessionStorage.getItem('ventasAppCompact')==='1');window.scrollTo({top:0,behavior:'smooth'});if(name==='history')loadHistory();if(name==='products')loadMobileProductCatalog();if(name==='cash')loadCash();if(name==='stock')loadMobileStock();if(name==='dashboard')loadMobileDashboard();if(name==='movementRegister')loadMovementRegister();if(name==='inventory')loadInventoryApp();if(name==='purchases'&&!nativePurchase.initialized)openPurchaseModule('manual',document.querySelector('[data-purchase-route="manual"]'))}
function loadInventoryApp(){const frame=$('inventoryAppFrame');if(frame&&!frame.getAttribute('src'))frame.src='/nuevo/index.html?inventory=mobile-red#/reporte/confrontacion'}
function loadMovementRegister(){const frame=$('movementRegisterFrame');if(frame&&!frame.src)frame.src='reporteregmovimiento.php?modo=app'}
function reloadMovementRegister(){const frame=$('movementRegisterFrame');if(!frame)return;if(!frame.src)return loadMovementRegister();frame.src=frame.src.split('#')[0]}
if(new URLSearchParams(location.search).get('view')==='movementRegister')window.addEventListener('DOMContentLoaded',()=>setTimeout(()=>showView('movementRegister'),120));
function loadMobileProductCatalog(){const frame=$('productAdminFrame');if(!frame||frame.getAttribute('src'))return;$('productAdminLoader')?.classList.remove('loaded');frame.src='../nuevo/index.html#/productos'}
function mobileProductCatalogLoaded(){
  $('productAdminLoader')?.classList.add('loaded');
  styleMobileProductCatalog();
  setTimeout(styleMobileProductCatalog,500);
  setTimeout(styleMobileProductCatalog,1600)
}
function styleMobileProductCatalog(){
  const frame=$('productAdminFrame');
  try{
    const doc=frame?.contentDocument;
    if(!doc||!doc.head||doc.location.href==='about:blank')return;
    let viewport=doc.querySelector('meta[name="viewport"]');
    if(!viewport){viewport=doc.createElement('meta');viewport.name='viewport';doc.head.appendChild(viewport)}
    viewport.content='width=device-width,initial-scale=1,maximum-scale=1,viewport-fit=cover';
    if(doc.getElementById('neuroMobileProductTheme'))return;
    const style=doc.createElement('style');
    style.id='neuroMobileProductTheme';
    style.textContent=`
      :root{--neuro-red:#bd1738;--neuro-red-dark:#690d25;--neuro-coral:#ef4d43;--neuro-soft:#fff4f6}
      html,body,#app{min-width:0!important;max-width:100%!important;background:#fff7f8!important}
