function bindMobileProductCodeGenerator(doc){
  if(doc.documentElement.dataset.neuroProductCodeGenerator==='1')return;
  doc.documentElement.dataset.neuroProductCodeGenerator='1';
  doc.addEventListener('click',async event=>{
    const button=event.target.closest?.('.product-form-new');
    if(!button)return;
    const form=button.closest('.product-form-content')||doc.querySelector('.product-form-content');
    const input=form?.querySelector('input[type="text"]');
    const codigoBase=String(input?.value||'').trim();
    if(!codigoBase)return;
    try{
      const response=await fetch(`/api/index.php/productos/codigo-siguiente/${encodeURIComponent(codigoBase)}`);
      const data=await response.json();
      if(!data.codigo)return;
      setTimeout(()=>{
        const target=(button.closest('.product-form-content')||doc.querySelector('.product-form-content'))?.querySelector('input[type="text"]');
        if(!target)return;
        const setter=Object.getOwnPropertyDescriptor(doc.defaultView.HTMLInputElement.prototype,'value')?.set;
        setter?setter.call(target,data.codigo):(target.value=data.codigo);
        target.dispatchEvent(new Event('input',{bubbles:true}));
        target.dispatchEvent(new Event('change',{bubbles:true}));
        target.focus();target.select()
      },120)
    }catch(error){console.warn('No se pudo generar el siguiente código de producto',error)}
  },true)
}
function reloadMobileProductCatalog(){const frame=$('productAdminFrame');if(!frame)return;$('productAdminLoader')?.classList.remove('loaded');const source=frame.getAttribute('src')||'../nuevo/index.html#/productos';frame.src='about:blank';setTimeout(()=>frame.src=source,80)}
