function ensureNativePurchaseModeSwitch(){if($('purchaseModeSwitch'))return;const search=document.querySelector('.va-purchase-product-search');if(!search)return;const bar=document.createElement('div');bar.id='purchaseModeSwitch';bar.className='va-sale-mode-switch va-purchase-mode-switch';bar.innerHTML='<button id="showPurchaseProductsMode" class="active" type="button" onclick="closeNativePurchaseCart()"><i class="fa fa-search"></i><span><b>Productos</b><small>Buscar y agregar</small></span></button><button id="showPurchaseCartMode" type="button" onclick="openNativePurchaseCart()"><i class="fa fa-shopping-basket"></i><span><b>Mi canasta</b><small id="purchaseModeSummary">0 productos · S/ 0.00</small></span><strong id="purchaseModeCount">0</strong></button>';search.parentNode.insertBefore(bar,search)}
