function openPurchaseModule(mode,button){nativePurchase.mode=mode==='order'?'order':'manual';document.querySelectorAll('[data-purchase-route]').forEach(item=>item.classList.toggle('active',item===button));$('purchaseOrderPicker').hidden=nativePurchase.mode!=='order';if(!nativePurchase.initialized)initNativePurchase();if(nativePurchase.mode==='order')loadNativePurchaseOrders()}
async function initNativePurchase(){nativePurchase.initialized=true;$('purchaseDate').value=localToday();try{const [providers,types,warehouses]=await Promise.all([api('/proveedores?q=&limit=30'),api('/movimientos/tipos?q='),api('/almacenes')]);nativePurchase.providers=asList(providers);$('purchaseMovementType').innerHTML=asList(types).filter(t=>Number(t.VaRegCompra)!==0).sort((a,b)=>Number(a.Tipo)-Number(b.Tipo)||Number(a.IdMovimientoTipo)-Number(b.IdMovimientoTipo)).map(t=>`<option value="${Number(t.IdMovimientoTipo)}" data-type='${escapeHtml(JSON.stringify(t))}'>${escapeHtml(t.TipoMovimiento)}</option>`).join('');const warehouseOptions=asList(warehouses).map(w=>`<option value="${Number(w.IdAlmacen)}">${escapeHtml(w.Almacen)}</option>`).join('');$('purchaseWarehouse').innerHTML=warehouseOptions;$('purchaseDestinationWarehouse').innerHTML=warehouseOptions;if(state.warehouse?.IdAlmacen)$('purchaseWarehouse').value=state.warehouse.IdAlmacen;if($('purchaseDestinationWarehouse').options.length>1&&$('purchaseDestinationWarehouse').value===$('purchaseWarehouse').value)$('purchaseDestinationWarehouse').selectedIndex=1;syncPurchaseDropdowns();updatePurchaseWarehouseMode();searchNativePurchaseProducts('',true)}catch(error){nativePurchase.initialized=false;toast(error.message||'No se pudo preparar el registro de compras.',true)}}
function purchaseDropdownMeta(id,text){if(id==='purchaseMovementType')return {icon:/TRASLADO/i.test(text)?'fa-exchange':/SALIDA|A PROVEEDOR/i.test(text)?'fa-sign-out':'fa-file-text-o',help:/TRASLADO/i.test(text)?'Movimiento entre almacenes':/SALIDA|A PROVEEDOR/i.test(text)?'Movimiento de salida':/FACTURA/i.test(text)?'Comprobante con RUC':/BOLETA/i.test(text)?'Comprobante de venta':'Movimiento de ingreso'};if(id==='purchaseWarehouse'||id==='purchaseDestinationWarehouse')return {icon:'fa-building-o',help:id==='purchaseDestinationWarehouse'?'Destino del traslado':Number(selectedPurchaseMovement().Tipo)===2||Number(selectedPurchaseMovement().Tipo)===1?'Origen del stock':'Destino del stock'};return {icon:'fa-money',help:/USD/i.test(text)?'Dólares americanos':'Soles peruanos'}}
function syncPurchaseDropdown(id){const select=$(id),button=$(id+'Button'),menu=$(id+'Menu');if(!select||!button||!menu)return;const options=[...select.options],selected=select.selectedOptions[0]||options[0],meta=purchaseDropdownMeta(id,selected?.textContent||'Seleccione');button.innerHTML=`<i class="fa ${meta.icon}"></i><span><b>${escapeHtml(selected?.textContent||'Seleccione')}</b><small>${escapeHtml(meta.help)}</small></span><i class="fa fa-chevron-down"></i>`;menu.innerHTML=options.map((option,index)=>{const itemMeta=purchaseDropdownMeta(id,option.textContent),active=option===selected;return `<button type="button" class="${active?'active':''}" onclick="choosePurchaseDropdown('${id}',${index})"><i class="fa ${itemMeta.icon}"></i><span><b>${escapeHtml(option.textContent)}</b><small>${escapeHtml(itemMeta.help)}</small></span><i class="fa ${active?'fa-check-circle':'fa-angle-right'}"></i></button>`}).join('')}
function syncPurchaseDropdowns(){['purchaseMovementType','purchaseWarehouse','purchaseDestinationWarehouse','purchaseCurrency'].forEach(syncPurchaseDropdown)}
function togglePurchaseDropdown(id){document.querySelectorAll('.va-smart-select.open').forEach(dropdown=>{if(dropdown.dataset.source!==id)dropdown.classList.remove('open')});document.querySelector(`.va-smart-select[data-source="${id}"]`)?.classList.toggle('open')}
function choosePurchaseDropdown(id,index){const select=$(id);select.selectedIndex=index;select.dispatchEvent(new Event('change',{bubbles:true}));syncPurchaseDropdown(id);if(id==='purchaseMovementType')updatePurchaseWarehouseMode();document.querySelector(`.va-smart-select[data-source="${id}"]`)?.classList.remove('open')}
function selectedPurchaseMovement(){const option=$('purchaseMovementType')?.selectedOptions?.[0];try{return JSON.parse(option?.dataset.type||'{}')}catch(error){return {}}}
