function renderNativeProviderResults(rows){const box=$('purchaseProviderResults');box._rows=rows;box.innerHTML=rows.map((p,i)=>`<button type="button" class="va-purchase-result" onclick="chooseNativePurchaseProvider(${i})"><span><b>${escapeHtml(p.Proveedor||'Proveedor')}</b><small>${escapeHtml(p.Ruc||'Sin documento')} · ${escapeHtml(p.Direccion||'Sin dirección')}</small></span><i class="fa fa-check-circle"></i></button>`).join('')}
function searchNativePurchaseProviders(query,showAll=false){clearTimeout(nativePurchase.providerTimer);const box=$('purchaseProviderResults'),q=String(query||'').trim();if(!showAll){nativePurchase.provider=null;$('purchaseProvider').value=''}if(q.length<2&&!showAll){box.innerHTML='';return}const load=async()=>{try{let rows;if(q.length<2&&nativePurchase.providers.length)rows=nativePurchase.providers;else{rows=asList(await api(`/proveedores?q=${encodeURIComponent(q.length>=2?q:'')}&limit=30`));if(q.length<2)nativePurchase.providers=rows}renderNativeProviderResults(rows);if(!rows.length)box.innerHTML='<div class="va-empty">No se encontraron proveedores.</div>'}catch(error){box.innerHTML='<div class="va-empty">No se pudo listar proveedores.</div>'}};if(showAll&&q.length<2)load();else nativePurchase.providerTimer=setTimeout(load,180)}
function chooseNativePurchaseProvider(index){const p=$('purchaseProviderResults')._rows?.[index]||nativePurchase.providers[index];if(!p)return;nativePurchase.provider=p;$('purchaseProvider').value=p.IdProveedor;$('purchaseProviderSearch').value=`${p.Ruc||''} · ${p.Proveedor||''}`;$('purchaseProviderResults').innerHTML=''}
