async function saveNewPurchaseProvider(){const ruc=$('purchaseProviderRuc').value.replace(/\D/g,''),name=$('purchaseProviderName').value.trim().toUpperCase(),address=$('purchaseProviderAddress').value.trim().toUpperCase(),note=$('purchaseProviderNote').value.trim();if(ruc.length!==8&&ruc.length!==11)return toast('Ingrese un RUC de 11 dígitos o documento de 8 dígitos.',true);if(name.length<3)return toast('Ingrese el nombre o razón social.',true);const button=$('savePurchaseProviderBtn');button.classList.add('va-loading');button.disabled=true;try{const result=await api('/proveedores',{method:'POST',body:JSON.stringify({Ruc:ruc,Proveedor:name,Direccion:address,Observacion:note})});if(!result.insertId)throw new Error('No se recibió el código del proveedor.');chooseNativePurchaseProviderFromData({IdProveedor:result.insertId,Ruc:ruc,Proveedor:name,Direccion:address});closeModal('newPurchaseProviderModal');toast('Proveedor registrado y seleccionado correctamente.')}catch(error){toast(error.message||'No se pudo registrar el proveedor.',true)}finally{button.classList.remove('va-loading');button.disabled=false}}
async function loadNativePurchaseOrders(){const select=$('purchaseOrderSelect'),status=$('purchaseOrderStatus');select.disabled=true;status.textContent='Cargando órdenes pendientes…';try{const orders=asList(await api(`/ordencompra?fechaDesde=2017-01-01&fechaHasta=${localToday()}&estado=0`));nativePurchase.orders=orders;select.innerHTML='<option value="">Seleccione una orden</option>'+orders.map(o=>`<option value="${Number(o.IdOrdenCompra)}">${escapeHtml((o.Correlativo||o.Anio+'-'+o.Numero)+' · '+o.Proveedor+' · '+money(o.Total))}</option>`).join('');status.textContent=orders.length?`${orders.length} orden(es) disponible(s).`:'No hay órdenes pendientes.'}catch(error){status.textContent='No se pudieron cargar las órdenes.';toast(error.message,true)}finally{select.disabled=false}}
async function loadNativePurchaseOrder(id){id=Number(id);if(!id)return;const order=nativePurchase.orders.find(o=>Number(o.IdOrdenCompra)===id),status=$('purchaseOrderStatus');status.textContent='Cargando productos de la orden…';try{const products=asList(await api(`/ordencompra/detalle?IdOrdenCompra=${id}`));if(!products.length)throw new Error('La orden no contiene productos.');nativePurchase.items=products.map(p=>purchaseItem(p,Number(p.Cantidad||p.cantidad),Number(p.Precio||p.precio)));chooseNativePurchaseProviderFromData(order);$('purchaseWarehouse').value=order.IdAlmacen||$('purchaseWarehouse').value;syncPurchaseDropdown('purchaseWarehouse');status.textContent=`Orden ${order.Correlativo}: ${products.length} producto(s) de ${order.Proveedor}.`;renderNativePurchaseItems()}catch(error){toast(error.message,true);status.textContent='No se pudo cargar la orden.'}}
function chooseNativePurchaseProviderFromData(p){nativePurchase.provider=p;$('purchaseProvider').value=p.IdProveedor;$('purchaseProviderSearch').value=`${p.Ruc||''} · ${p.Proveedor||''}`;$('purchaseProviderResults').innerHTML=''}
function purchaseItem(p,qty=1,cost=null){return {IdProducto:Number(p.IdProducto),Producto:p.Producto||'Producto',CodigoBarra:p.CodigoBarra||'',cantidad:Number(qty)||1,precio:cost===null?Number(p.PrecioCosto||0):Number(cost),nuevoPrecioContado:Number(p.PrecioContado||p.precioVenta||p.Precio||cost||0),TieneIgv:Number(p.TieneIgv||0),IdLote:Number(p.IdLote||0)}}
function renderNativePurchaseSearchRows(rows){const box=$('purchaseProductResults');box._rows=rows;box.innerHTML=rows.length?`<div class="va-product-result-summary"><i class="fa fa-cubes"></i> ${rows.length} productos encontrados · use − y + para cambiar la cantidad</div>`+rows.map((p,i)=>{const id=Number(p.IdProducto),selected=nativePurchase.items.find(item=>item.IdProducto===id),qty=selected?Number(selected.cantidad||0):0;return `<article class="va-purchase-result${selected?' is-selected':''}" role="button" tabindex="0" onclick="${selected?`focusNativePurchaseItem(${id})`:`addNativePurchaseProduct(${i})`}" onkeydown="if(event.key==='Enter'){${selected?`focusNativePurchaseItem(${id})`:`addNativePurchaseProduct(${i})`}}"><span class="va-purchase-result-copy"><b>${escapeHtml(p.Producto)}</b><small class="va-purchase-result-meta"><span><i class="fa fa-tag"></i> ${escapeHtml(p.Marca||'Sin marca')}</span><span><i class="fa fa-cube"></i> ${escapeHtml(p.Modelo||'Sin modelo')}</span><span><i class="fa fa-barcode"></i> ${escapeHtml(p.CodigoBarra||'Sin código')}</span></small></span><span class="va-purchase-result-action"><strong>${selected?'En canasta':money(p.PrecioCosto)}</strong>${selected?`<span class="va-purchase-result-qty-control"><button type="button" onclick="event.stopPropagation();changeNativePurchaseQuantity(${id},-1)" aria-label="Disminuir cantidad"><i class="fa fa-minus"></i></button><output>${qty}</output><button type="button" onclick="event.stopPropagation();changeNativePurchaseQuantity(${id},1)" aria-label="Aumentar cantidad"><i class="fa fa-plus"></i></button></span>`:`<i class="fa fa-plus"></i>`}</span></article>`}).join(''):'<div class="va-empty">No se encontraron productos.</div>'}
function refreshNativePurchaseSearchRows(){const box=$('purchaseProductResults');if(Array.isArray(box?._rows)&&box._rows.length)renderNativePurchaseSearchRows(box._rows)}
function searchNativePurchaseProducts(query,force=false){clearTimeout(nativePurchase.searchTimer);const box=$('purchaseProductResults'),term=String(query||'').trim();if(term.length<2&&!force){box.innerHTML='';return}nativePurchase.searchTimer=setTimeout(async()=>{try{renderNativePurchaseSearchRows(asList(await api(`/productos?q=${encodeURIComponent(term)}&limit=30`)))}catch(error){box.innerHTML='<div class="va-empty">No se pudo listar los productos.</div>'}},force?0:260)}
