function setPurchaseVoiceState(listening){purchaseVoiceListening=listening;const button=$('purchaseVoiceSearchBtn');if(!button)return;button.classList.toggle('is-listening',listening);button.setAttribute('aria-pressed',listening?'true':'false');button.title=listening?'Escuchando… toque para detener':'Buscar productos por voz';button.innerHTML=`<i class="fa ${listening?'fa-stop':'fa-microphone'}"></i>`}
function togglePurchaseVoiceSearch(){const SpeechRecognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SpeechRecognition)return toast('La búsqueda por voz no está disponible en este navegador.',true);if(purchaseVoiceListening&&purchaseVoiceRecognition){purchaseVoiceRecognition.stop();return}purchaseVoiceRecognition=new SpeechRecognition();purchaseVoiceRecognition.lang='es-PE';purchaseVoiceRecognition.continuous=false;purchaseVoiceRecognition.interimResults=false;purchaseVoiceRecognition.maxAlternatives=1;purchaseVoiceRecognition.onstart=()=>{setPurchaseVoiceState(true);toast('Escuchando… diga el nombre del producto')};purchaseVoiceRecognition.onresult=event=>{const phrase=(event.results?.[0]?.[0]?.transcript||'').trim();if(!phrase)return;$('purchaseProductSearch').value=phrase;searchNativePurchaseProducts(phrase,true);toast(`Buscando: ${phrase}`)};purchaseVoiceRecognition.onerror=event=>{if(event.error!=='aborted'&&event.error!=='no-speech')toast(event.error==='not-allowed'?'Permita el uso del micrófono para buscar por voz.':'No se pudo reconocer la voz.',true)};purchaseVoiceRecognition.onend=()=>setPurchaseVoiceState(false);try{purchaseVoiceRecognition.start()}catch(error){setPurchaseVoiceState(false);toast('No se pudo iniciar el micrófono.',true)}}
