function elegantAppConfirm(data){
    let modal=$('appElegantConfirm');
    if(!modal){
        modal=document.createElement('div');
        modal.id='appElegantConfirm';
        modal.className='va-modal va-elegant-confirm';
        modal.innerHTML='<section class="va-elegant-confirm-card" role="dialog" aria-modal="true" aria-labelledby="appConfirmTitle"><header class="va-elegant-confirm-head"><span class="va-elegant-confirm-icon"><i class="fa fa-shield"></i></span><span><b id="appConfirmTitle">CONFIRMAR REGISTRO</b><small>REVISE LOS DATOS ANTES DE CONTINUAR</small></span></header><div id="appConfirmBody" class="va-elegant-confirm-body"></div><footer class="va-elegant-confirm-actions"><button id="appConfirmReview" class="va-elegant-confirm-review" type="button"><i class="fa fa-arrow-left"></i> REVISAR</button><button id="appConfirmAccept" class="va-elegant-confirm-accept" type="button"><i class="fa fa-check-circle"></i> CONFIRMAR</button></footer></section>';
        document.body.appendChild(modal);
    }
    $('appConfirmTitle').textContent=data.title||'CONFIRMAR REGISTRO';
    $('appConfirmBody').innerHTML=`<div class="va-elegant-confirm-document"><small>COMPROBANTE</small><strong>${escapeHtml(data.document||'-')}</strong></div><div class="va-elegant-confirm-grid"><div class="va-elegant-confirm-data"><small>PROVEEDOR</small><strong>${escapeHtml(data.provider||'-')}</strong></div><div class="va-elegant-confirm-data"><small>PRODUCTOS</small><strong>${Number(data.products)||0} PRODUCTOS</strong></div><div class="va-elegant-confirm-data"><small>UNIDADES</small><strong>${Number(data.units)||0} UNIDADES</strong></div><div class="va-elegant-confirm-data"><small>ALMACÉN</small><strong>${escapeHtml(data.warehouse||'-')}</strong></div></div><div class="va-elegant-confirm-total"><span>TOTAL A REGISTRAR</span><strong>${escapeHtml(data.total||'S/ 0.00')}</strong></div><p class="va-elegant-confirm-note"><i class="fa fa-info-circle"></i><span>AL CONFIRMAR, ESTA OPERACIÓN ACTUALIZARÁ EL STOCK DEL ALMACÉN.</span></p>`;
    modal.classList.add('open');
    return new Promise(resolve=>{
        const finish=value=>{modal.classList.remove('open');resolve(value)};
        $('appConfirmReview').onclick=()=>finish(false);
        $('appConfirmAccept').onclick=()=>finish(true);
        modal.onclick=event=>{if(event.target===modal)finish(false)};
    });
}
