function updateMixedBalance(){const balance=$('mixedBalance');if(!balance)return;const assigned=[...document.querySelectorAll('[data-mixed-amount]')].reduce((sum,input)=>sum+Number(input.value||0),0),difference=cartTotal()-assigned,ok=Math.abs(difference)<.01;balance.classList.toggle('ok',ok);balance.innerHTML=ok?'<span><i class="fa fa-check-circle"></i> Total distribuido</span><strong>Correcto</strong>':`<span>${difference>0?'Falta distribuir':'Monto excedido'}</span><strong>${money(Math.abs(difference))}</strong>`}
