async function openCashMovementForm(){openModal('cashMovementModal');$('movementDate').value=localToday();$('movementConcept').value='';$('movementAmount').value='';$('movementType').innerHTML='<option>Cargando operaciones...</option>';$('movementAccount').innerHTML='<option>Cargando cuentas...</option>';try{const [types,accounts]=await Promise.all([api('/ListarTipoOpe'),api('/cuentas/listarcuentas')]);cashMovementTypes=asList(types);cashMovementAccounts=asList(accounts);$('movementAccount').innerHTML=cashMovementAccounts.length?cashMovementAccounts.map(account=>`<option value="${Number(account.IdCuenta)}">${escapeHtml(account.Cuenta||'Cuenta')}</option>`).join(''):'<option value="">No hay cuentas disponibles</option>';setCashMovementKind(0)}catch(error){toast(error.message||'No se pudo cargar Caja/Bancos.',true)}}
function setCashMovementKind(kind){cashMovementKind=Number(kind);$('movementIncomeTab').classList.toggle('active',cashMovementKind===0);$('movementExpenseTab').classList.toggle('active',cashMovementKind===1);const filtered=cashMovementTypes.filter(type=>Number(type.Tipo)===cashMovementKind);$('movementType').innerHTML=filtered.length?filtered.map(type=>`<option value="${Number(type.IdTipoCajaBanco)}">${escapeHtml(type.TipoCajaBanco||'Operación')}</option>`).join(''):'<option value="">No hay tipos disponibles</option>';const button=$('saveCashMovementBtn');button.className=`va-btn ${cashMovementKind===0?'green':'red'} va-movement-save`;button.innerHTML=`<i class="fa fa-save"></i> Registrar ${cashMovementKind===0?'ingreso':'gasto'}`}
async function saveCashMovement(){const type=Number($('movementType').value),account=Number($('movementAccount').value),date=$('movementDate').value,concept=$('movementConcept').value.trim(),amount=Number($('movementAmount').value);if(!type)return toast('Seleccione el tipo de operación.',true);if(!account)return toast('Seleccione una cuenta.',true);if(!date)return toast('Seleccione la fecha.',true);if(!concept)return toast('Ingrese el concepto del movimiento.',true);if(!(amount>0))return toast('Ingrese un importe mayor a cero.',true);const button=$('saveCashMovementBtn');button.classList.add('va-loading');try{await api('/movimiento/guardarMovimiento',{method:'POST',body:JSON.stringify({IdTipoCajaBanco:type,IdCuenta:account,FechaDoc:date,Concepto:concept,Importe:amount,TipoCajaBanco:cashMovementKind,AplicadoDocVenta:[],IdCliente:0,IdProveedor:0,User:VA_USER})});closeModal('cashMovementModal');toast(`${cashMovementKind===0?'Ingreso':'Gasto'} registrado correctamente`);await loadCash();await openCashBankMovements()}catch(error){toast(error.message||'No se pudo registrar el movimiento.',true)}finally{button.classList.remove('va-loading')}}
function escapeHtml(v){return String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
document.addEventListener('click',event=>{if(!event.target.closest('.va-doc-field'))closeDocTypeMenu()});
document.addEventListener('click',event=>{if(!event.target.closest('.va-smart-select'))document.querySelectorAll('.va-smart-select.open').forEach(dropdown=>dropdown.classList.remove('open'));if(!event.target.closest('.va-purchase-autocomplete')){const results=$('purchaseProviderResults');if(results)results.innerHTML=''}});
document.addEventListener('input',event=>{if(event.target.matches('[data-mixed-amount]'))rebalanceMixedPayment(event.target)});
function ensureSaleOrganizationUi(){if($('saleIsOrganization'))return;const fields=document.querySelector('.va-sale-fields');if(!fields)return;const row=document.createElement('div');row.className='va-organization-row';row.innerHTML='<label class="va-organization-toggle"><input id="saleIsOrganization" type="checkbox"><span>Es organizaci&oacute;n</span></label><input id="saleOrganizationName" class="va-input va-organization-name" maxlength="150" autocomplete="organization" placeholder="Escriba el nombre de la organizaci&oacute;n" hidden>';fields.insertAdjacentElement('afterend',row);$('saleIsOrganization').addEventListener('change',event=>toggleSaleOrganization(event.target.checked))}
function toggleSaleOrganization(enabled){const input=$('saleOrganizationName');if(!input)return;input.hidden=!enabled;if(!enabled){input.value='';return}setTimeout(()=>input.focus(),40)}
const ventasAppModuleDefinitions={inventory:{label:'Confrontación de inventario',icon:'barcode',help:'Cámara, conteo físico y confrontación'},sale:{label:'Realizar venta',icon:'shopping-cart',help:'Boletas, facturas y notas'},products:{label:'Productos',icon:'cubes',help:'Catálogo, precios y edición'},history:{label:'Ventas realizadas',icon:'list-alt',help:'Historial de comprobantes'},cash:{label:'Cierre de caja',icon:'power-off',help:'Resumen y cierre del turno'},movements:{label:'Ingresos y gastos',icon:'exchange',help:'Movimientos de Caja/Bancos'},purchases:{label:'Compras',icon:'truck',help:'Compras y proveedores'},stock:{label:'Stock valorizado',icon:'archive',help:'Existencias y valorización'},dashboard:{label:'Dashboard',icon:'line-chart',help:'Indicadores del negocio'},movementRegister:{label:'Registro de movimientos',icon:'exchange',help:'Entradas, salidas, compras y traslados'}};
let ventasAppModuleConfig=Object.fromEntries(Object.keys(ventasAppModuleDefinitions).map(key=>[key,true]));
function appModuleKeyForElement(element){const action=element?.getAttribute('onclick')||'',nav=element?.dataset?.nav;if(nav&&ventasAppModuleDefinitions[nav])return nav;if(action.includes("showView('sale')"))return'sale';if(action.includes("showView('products')"))return'products';if(action.includes("showView('history')"))return'history';if(action.includes("showView('cash')"))return'cash';if(action.includes('openCashMovementForm'))return'movements';if(action.includes("showView('purchases')"))return'purchases';if(action.includes("showView('inventory')"))return'inventory';if(action.includes("showView('stock')"))return'stock';if(action.includes("showView('dashboard')"))return'dashboard';if(action.includes("showView('movementRegister')"))return'movementRegister';return''}
function applyAppModuleConfig(){document.querySelectorAll('.va-grid>.va-card,.va-nav button[data-nav]').forEach(element=>{const key=appModuleKeyForElement(element);if(!key)return;const locked=ventasAppModuleConfig[key]===false;element.hidden=false;element.disabled=locked;element.classList.toggle('module-locked',locked);element.setAttribute('aria-disabled',locked?'true':'false');if(locked)element.title='Módulo deshabilitado por el administrador';else element.removeAttribute('title')})}
function ensureAppModulePanel(canEdit){if($('appModulePanel'))return;if(canEdit){const card=document.createElement('button');card.type='button';card.className='va-card va-module-admin-card';card.innerHTML='<i class="fa fa-sliders"></i><b>Configurar módulos</b><small>Habilitar o deshabilitar botones</small>';card.onclick=openAppModulePanel;document.querySelector('.va-view[data-view="home"] .va-grid')?.appendChild(card)}const modal=document.createElement('div');modal.id='appModulePanel';modal.className='va-modal';modal.onclick=event=>{if(event.target===modal)closeModal('appModulePanel')};modal.innerHTML='<div class="va-modal-card va-module-panel"><div class="va-modal-head"><div><small>SUPERADMINISTRADOR</small><h3>Botones de la app</h3></div><button class="va-close" onclick="closeModal(\'appModulePanel\')">×</button></div><div id="appModuleList" class="va-module-list"></div><div class="va-module-actions"><button class="va-btn gray" onclick="closeModal(\'appModulePanel\')">Cancelar</button><button class="va-btn red" onclick="saveAppModuleConfig()"><i class="fa fa-save"></i> Guardar</button></div></div>';document.body.appendChild(modal)}
function renderAppModulePanel(){const list=$('appModuleList');if(!list)return;list.innerHTML=Object.entries(ventasAppModuleDefinitions).map(([key,item])=>`<label class="va-module-option"><i class="fa fa-${item.icon}"></i><span><b>${item.label}</b><small>${item.help}</small></span><input type="checkbox" data-module-toggle="${key}" ${ventasAppModuleConfig[key]!==false?'checked':''}></label>`).join('')}
function openAppModulePanel(){renderAppModulePanel();openModal('appModulePanel')}
async function initAppModuleControl(){try{const result=await api('/ventas-app/modulos');ventasAppModuleConfig=Object.fromEntries(Object.keys(ventasAppModuleDefinitions).map(key=>[key,Number(result.modules?.[key]??1)===1]));ensureAppModulePanel(Boolean(result.canEdit));applyAppModuleConfig()}catch(error){applyAppModuleConfig()}}
async function saveAppModuleConfig(){const modules={};document.querySelectorAll('[data-module-toggle]').forEach(input=>modules[input.dataset.moduleToggle]=input.checked?1:0);try{const result=await api('/ventas-app/modulos',{method:'POST',body:JSON.stringify({modules})});ventasAppModuleConfig=Object.fromEntries(Object.keys(ventasAppModuleDefinitions).map(key=>[key,Number(result.modules?.[key]??1)===1]));applyAppModuleConfig();closeModal('appModulePanel');toast('Botones actualizados correctamente')}catch(error){toast(error.message||'No se pudo guardar la configuración.',true)}}
const ventasAppOrganizationApi=api;
api=async function(path,options={}){const method=String(options.method||'GET').toUpperCase(),writesSale=(path==='/ventas'||path==='/proformas')&&method==='POST';if(writesSale){const enabled=Boolean($('saleIsOrganization')?.checked),name=String($('saleOrganizationName')?.value||'').replace(/\s+/g,' ').trim().toUpperCase();if(enabled&&!name){$('saleOrganizationName')?.focus();throw new Error('Escriba el nombre de la organizaciÃ³n.')}const payload=JSON.parse(options.body||'{}');payload.EsOrganizacion=enabled?1:0;payload.nombreOrganizacion=enabled?name:'';payload.NombreOrganizacion=enabled?name:'';options={...options,body:JSON.stringify(payload)}}const response=await ventasAppOrganizationApi(path,options);if(path==='/ventas'&&method==='POST'){$('saleIsOrganization').checked=false;toggleSaleOrganization(false)}return response};
document.addEventListener('DOMContentLoaded',()=>{setNightMode(localStorage.getItem('ventasAppNightMode')==='1');setAppBannerHidden(localStorage.getItem('ventasAppBannerHidden')==='1');setNativePurchaseProductListHidden(localStorage.getItem('purchaseProductListHidden')==='1');ensureMixedPaymentUi();ensureSaleOrganizationUi();ensureSaleEmailButton();ensureClientDocumentLookup();initMailAdministration();initAppModuleControl();setNavCompact(localStorage.getItem('neuroAppNavCompact')==='1');renderCart();bindLiveClientSearch('clientSearch','clientList',false);bindLiveClientSearch('pickerSearch','pickerClients',true);initApp()});
</script>

